/* ==========================================================
   CINEMATIC HERO — the first screen's grade and proof band.

   The name carries the composition at poster scale, the robot
   is lifted out of the layout and bled off the right edge,
   and everything quantitative collapses into one full-bleed
   band welded to the bottom edge. The boxed stat-tile widget
   that used to sit mid-column is gone.
   ========================================================== */
import React, { useEffect, useLayoutEffect, useRef } from "react";
import "./heroCinematic.css";

/* The four proof numbers. Static strings rather than the animated counters
   the old tile row used: at this size the count-up read as a loading state. */
export const HERO_STATS = [
  { value: "80K+", label: "docs / month" },
  { value: "95%", label: "AI accuracy" },
  { value: "300+", label: "students mentored" },
  { value: "60%", label: "faster APIs" },
];

/* Light shaft, vignette and film grain. Pure decoration, sits under the copy
   and over the ambient orbs. */
export function CinematicLayer() {
  return (
    <div className="hv-cine" aria-hidden="true">
      <div className="hv-cine-shaft" />
      <div className="hv-cine-vignette" />
      <div className="hv-cine-grain" />
    </div>
  );
}

/* Full-bleed band pinned to the bottom of the viewport-height hero.
   `counter` is the live visitor readout, handed in from Greeting so the
   Firestore subscription stays in one place. It takes the left slot, which
   is otherwise dead space behind the fixed JARVIS pill. */
/* `credentials` is no longer rendered here: the same two lines are now the
   pedigree row under the hero's role, and showing them in both places meant
   the copy appeared twice on mobile, where this band is in the flow. */
export function ProofBar({ counter }) {
  return (
    <div className="hv-proofbar">
      <div className="hv-proofbar-live">{counter}</div>

      <div className="hv-proofbar-main">
        <div className="hv-proofbar-stats">
          {HERO_STATS.map((s) => (
            <div className="hv-proofbar-stat" key={s.label}>
              <span className="hv-proofbar-num">{s.value}</span>
              <span className="hv-proofbar-lab">{s.label}</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

/* ==========================================================
   THE NAME, ALIVE
   ----------------------------------------------------------
   The name is the largest thing on the screen, so it is where
   the first-second moment belongs — not in another widget.

   1. Arrival: each letter rises out of a blur, one after the
      other, then a single sheen of light crosses the word.
   2. Presence: on a desktop pointer, the letters nearest the
      cursor lift and brighten a little, like type on a magnet.

   Each letter paints its own slice of ONE gradient: it carries
   the word's width and its own offset (--w, --x) and positions
   the gradient against them, so the colour runs across the
   word unbroken even though every letter moves on its own.
   (background-clip:text on the parent cannot follow children
   that are transformed.)
   ========================================================== */
const LIFT_RADIUS = 220; // px from a letter's centre where the pull starts

export function HeroName({ name }) {
  const wordRef = useRef(null);
  const chars = Array.from(name);

  // Measure each letter's offset inside the word for the shared gradient.
  useLayoutEffect(() => {
    const word = wordRef.current;
    if (!word) return undefined;
    const measure = () => {
      const w = word.offsetWidth;
      if (!w) return;
      word.style.setProperty("--w", `${w}px`);
      word.querySelectorAll(".hv-ch").forEach((ch) => {
        ch.style.setProperty("--x", `${ch.offsetLeft}px`);
      });
    };
    measure();
    let ro;
    if (typeof ResizeObserver !== "undefined") {
      ro = new ResizeObserver(measure);
      ro.observe(word);
    }
    if (document.fonts && document.fonts.ready) document.fonts.ready.then(measure);
    return () => ro && ro.disconnect();
  }, [name]);

  // Letters lean toward the cursor. rAF-throttled, desktop pointers only.
  useEffect(() => {
    const word = wordRef.current;
    if (!word) return undefined;
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches)
      return undefined;
    if (!window.matchMedia("(pointer: fine)").matches) return undefined;

    const letters = Array.from(word.querySelectorAll(".hv-ch"));
    let raf = null;
    let px = -9999;
    let py = -9999;

    const apply = () => {
      raf = null;
      letters.forEach((el) => {
        const r = el.getBoundingClientRect();
        // The lift itself moves the rect; measure from the resting centre.
        const lift = parseFloat(el.style.getPropertyValue("--lift")) || 0;
        const cx = r.left + r.width / 2;
        const cy = r.top + r.height / 2 + lift * r.height * 0.09;
        const d = Math.hypot(px - cx, py - cy);
        const t = Math.max(0, 1 - d / LIFT_RADIUS);
        const eased = t * t * (3 - 2 * t);
        el.style.setProperty("--lift", eased.toFixed(3));
      });
    };

    const onMove = (e) => {
      px = e.clientX;
      py = e.clientY;
      if (!raf) raf = requestAnimationFrame(apply);
    };
    const onLeave = () => {
      px = -9999;
      py = -9999;
      if (!raf) raf = requestAnimationFrame(apply);
    };

    window.addEventListener("mousemove", onMove, { passive: true });
    document.addEventListener("mouseleave", onLeave);
    return () => {
      window.removeEventListener("mousemove", onMove);
      document.removeEventListener("mouseleave", onLeave);
      if (raf) cancelAnimationFrame(raf);
    };
  }, []);

  return (
    <span className="hv-name" ref={wordRef}>
      {/* Screen readers get the word once, not six letters. */}
      <span className="hv-sr">{name}</span>
      {chars.map((c, i) => (
        <span
          key={i}
          className="hv-ch"
          aria-hidden="true"
          style={{ "--i": i, "--n": chars.length }}
        >
          {c}
        </span>
      ))}
    </span>
  );
}

